const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define South Los Angeles region
  const losAngelesAOI = ee.Geometry.Point([-118.2, 33.9]).buffer(50000);

  // Time periods: October 1-23
  const startDay = '-10-01';
  const endDay = '-10-24';

  const date2018Start = '2018' + startDay;
  const date2018End = '2018' + endDay;
  const date2019Start = '2019' + startDay;
  const date2019End = '2019' + endDay;
  const date2021Start = '2021' + startDay;
  const date2021End = '2021' + endDay;

  // Function to get TROPOMI NO2 data and calculate mean
  async function getMeanNO2(startDate, endDate, year) {
    const collection = ee.ImageCollection('COPERNICUS/S5P/NRTI_L3_NO2')
      .filterBounds(losAngelesAOI)
      .filterDate(startDate, endDate)
      .select('NO2_column_ppb');

    const size = collection.size().getInfo();

    if (size === 0) {
      console.log(`${year}: No images found`);
      return null;
    }

    // Filter by QA value (>0.5)
    const filtered = collection.map(img => img.updateMask(img.select('QA_VALUE').gte(0.5)));

    // Calculate pixel count
    const countImg = filtered.select('NO2_column_ppb').first();
    if (countImg === null || countImg === undefined) {
      console.log(`${year}: First image null`);
      return null;
    }

    const countDict = countImg.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: losAngelesAOI,
      scale: 3000,
      maxPixels: 1e9
    }).getInfo();

    const pixelCount = countDict['NO2_column_ppb'] || 0;

    if (pixelCount === 0) {
      console.log(`${year}: No valid pixels after QA filtering`);
      return null;
    }

    // Calculate mean NO2
    const meanDict = countImg.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: losAngelesAOI,
      scale: 3000,
      maxPixels: 1e9
    }).getInfo();

    const meanNO2 = meanDict['NO2_column_ppb'];

    if (meanNO2 === null || meanNO2 === undefined || isNaN(meanNO2)) {
      console.log(`${year}: Invalid mean value`);
      return null;
    }

    console.log(`${year}: Imgs=${size}, ValidPx=${pixelCount}, Mean=${meanNO2.toFixed(3)} ppb`);
    return meanNO2;
  }

  // Get data for all three years
  const mean2018 = await getMeanNO2(date2018Start, date2018End, '2018');
  const mean2019 = await getMeanNO2(date2019Start, date2019End, '2019');
  const mean2021 = await getMeanNO2(date2021Start, date2021End, '2021');

  // Validate data
  if (mean2018 === null || mean2019 === null || mean2021 === null) {
    console.log('Missing data for comparison');
    console.log('C1');
    return;
  }

  // Compare 2021 to average of 2018 and 2019
  const meanHistorical = (mean2018 + mean2019) / 2;
  console.log(`Avg(2018,2019): ${meanHistorical.toFixed(3)} ppb`);
  console.log(`2021 / Avg: ${(mean2021 / meanHistorical).toFixed(3)}`);

  if (mean2021 < meanHistorical) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
